define({"topics":[{"title":"Installing Trellix ePolicy Orchestrator (ePO)","shortdesc":"<p class=\"shortdesc\">The customer takes on the responsibility of checking that they meet the product requirements, downloading the Trellix ePolicy Orchestrator (ePO) software, and configuring the server appropriately.<\/p>","href":"t_Installing_Trellix_ePolicy_Orchestrator.html","attributes":{"data-id":"id_2025041"},"menu":{"hasChildren":false},"tocID":"id_2025041-d46e35008","topics":[]},{"title":"Updating Trellix ePolicy Orchestrator (ePO)","shortdesc":"<p class=\"shortdesc\">After the Trellix ePolicy Orchestrator (ePO) ePO server is properly installed by the customer, the customer also owns the process of updating the ePO software in accordance to Trellix’s recommendations. These steps are only to be referenced by the FE if the customer has questions.<\/p>","href":"t_Updating_McAfee_ePolicy_Orchestrator.html","attributes":{"data-id":"id_2025042"},"menu":{"hasChildren":false},"tocID":"id_2025042-d46e35112","topics":[]},{"title":"Connecting an MR system to a Trellix ePolicy Orchestrator (ePO) server","shortdesc":"<p class=\"shortdesc\">Follow this procedure to connect a GE HealthCare MR system to a Trellix ePolicy Orchestrator server (ePO) server.<\/p>","href":"t_Connecting_a_MR_target_to_a_McAfee_ePolicy_Orchestrator_server.html","attributes":{"data-id":"id_2025045"},"menu":{"hasChildren":false},"tocID":"id_2025045-d46e35216","topics":[]},{"title":"Updating Trellix ePolicy Orchestrator (ePO) DAT or Engine files using a USB drive","shortdesc":"<p class=\"shortdesc\">This is a breakdown of the process of updating a .dat file or engine file on an MR system using a USB drive, in the case that Trellix ePolicy Orchestrator (ePO) product deployment is not an option.<\/p>","href":"t_UpdatingDATfileWOePO.html","attributes":{"data-id":"id_2025136"},"menu":{"hasChildren":true},"tocID":"id_2025136-d46e35320","next":"id_2025136-d46e35320"},{"title":"Scanning an MR system connected to a Trellix ePolicy Orchestrator (ePO) server","shortdesc":"<p class=\"shortdesc\">Scan an MR system connected to a Trellix ePolicy Orchestrator server (ePO).<\/p>","href":"t_ScanningAnMRTargetConnectedToMcAfeeEPolicyOrchestratorServer.html","attributes":{"data-id":"id_2025044"},"menu":{"hasChildren":false},"tocID":"id_2025044-d46e35632","topics":[]}]});